module BeachFoodTruck #(\n    parameter N = 5,\n    parameter DATA_WIDTH = 8,\n    parameter IDX_WIDTH = 3\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [IDX_WIDTH-1:0] addr,\n    input wire [DATA_WIDTH-1:0] data_in,\n    input wire wr_en,\n    output reg [IDX_WIDTH-1:0] optimal_pos,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [DATA_WIDTH-1:0] hut [0:N-1];\n    reg [11:0] total;\n    reg [11:0] prefix [0:N-1];\n    reg [12:0] diff [0:N-1];\n    reg [12:0] min_diff;\n    integer i;\n\n    // Initialize all registers\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            optimal_pos <= 3'd0;\n            total <= 12'd0;\n            min_diff <= 13'd0;\n            for (i = 0; i < N; i = i + 1) begin\n                hut[i] <= 8'd0;\n                prefix[i] <= 12'd0;\n                diff[i] <= 13'd0;\n            end\n        end else begin\n            // Handle write enable\n            if (wr_en) begin\n                hut[addr] <= data_in;\n            end\n\n            // State machine\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    // Compute total population\n                    total <= 12'd0;\n                    for (i = 0; i < N; i = i + 1) begin\n                        total <= total + hut[i];\n                    end\n\n                    // Compute prefix sums\n                    prefix[0] <= hut[0];\n                    for (i = 1; i < N; i = i + 1) begin\n                        prefix[i] <= prefix[i-1] + hut[i];\n                    end\n\n                    // Compute diff for each position\n                    for (i = 0; i < N; i = i + 1) begin\n                        reg [12:0] temp_diff;\n                        reg [12:0] abs_val;\n                        reg [12:0] two_prefix_plus_hut;\n\n                        two_prefix_plus_hut = (2 * prefix[i]) + hut[i];\n                        abs_val = (two_prefix_plus_hut > total) ? (two_prefix_plus_hut - total) : (total - two_prefix_plus_hut);\n                        temp_diff = abs_val - (hut[i] & 1);\n                        diff[i] = (temp_diff < 0) ? 13'd0 : temp_diff;\n                    end\n\n                    // Find minimum diff\n                    min_diff <= diff[0];\n                    optimal_pos <= 3'd0;\n                    for (i = 1; i < N; i = i + 1) begin\n                        if (diff[i] < min_diff) begin\n                            min_diff <= diff[i];\n                            optimal_pos <= i;\n                        end\n                    end\n\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule